#[cfg(test)]
mod review_final_probes {
    use super::*;
    #[test]
    fn windows_absolute_class_matches_an_unintended_subtree() {
        let root = tempfile::tempdir().unwrap();
        let body = r"back[s\]lash";
        let typed = format!("{}/{body}", root.path().display());
        let resolved = resolve_excludes_on(&[typed], Some(root.path()), true);
        assert_eq!(resolved.patterns, ["back[s/]lash"]);
        let native = globset::Glob::new(body).unwrap().compile_matcher();
        assert!(native.is_match("backslash"));
        assert!(!native.is_match("back/lash"));
        let mut filter = FileFilter::default();
        filter.exclude_files = resolved.patterns.clone();
        for name in ["backslash/saved.txt", "back/lash/saved.txt"] {
            assert!(!filter.allows_entry(Some(Path::new(name)), Path::new(name), 1, None));
        }
        println!("resolved={resolved:?}; extra exclusion: back/lash/saved.txt");
    }
    #[test]
    fn windows_pairing_does_not_pair_final_sigma() {
        let listed = vec!["σ".to_string()];
        assert_eq!(paired_by_case("ς", &listed), None);
        assert_eq!(paired_by_case("Σ", &listed), Some("σ".to_string()));
        println!("Windows branch: final sigma -> None; capital sigma -> stored sigma");
    }
}
